#ifndef CU_REGULAR_SET_DATA_HPP
#define CU_REGULAR_SET_DATA_HPP

#include "CU/types.hpp"

/**
 * @brief Plain data describing a regular set.
 *
 * The set is the union of a finite aperiodic part and a periodic part
 * generated by adding multiples of @c period to each element of
 * @c periodic. When @c period is zero the set is finite and @c periodic
 * must be empty.
 */
struct RegularSetData
{
    data_t finite;      ///< Finite (aperiodic) part of the set.
    data_t periodic;    ///< Bases of the periodic components.
    num_t period = 0;   ///< Common period of the periodic components.
};

#endif // CU_REGULAR_SET_DATA_HPP